<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({dealers:[],orders:[],rebates:[]}),msg=ref('');const orderValue=computed(()=>data.value.orders.reduce((n,x)=>n+x.totalAmount,0));async function load(){try{data.value=await request('/api/dealer-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/dealer-ops/dealers',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',dealerCode:'DLR-'+Date.now(),name:'华东区域渠道伙伴',taxNo:'91310000'+Date.now(),agreementEnd:'2027-12-31'})});msg.value='经销商档案已建立，等待准入审核';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>CHANNEL OPERATIONS</small><h3>渠道伙伴经营中心</h3><p>围绕准入、授权、价格、信用、订单与返利统一渠道经营规则。</p></div><button @click="create">登记渠道伙伴</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>渠道伙伴</span><b>{{data.dealers.length}}</b><small>准入与协议状态</small></article><article><span>渠道订单额</span><b>¥{{orderValue.toLocaleString()}}</b><small>价格与信用门禁</small></article><article><span>返利申请</span><b>{{data.rebates.length}}</b><small>申请、审批、结算</small></article></section><section class="board"><article><header><h4>伙伴信用视图</h4><button @click="load">刷新</button></header><div class="line" v-for="x in data.dealers" :key="x.id"><div><b>{{x.name}}</b><small>{{x.dealerCode}} · 已用 ¥{{x.creditUsed.toLocaleString()}} / ¥{{x.creditLimit.toLocaleString()}}</small></div><em>{{x.status}}</em></div><p v-if="!data.dealers.length">暂无专业经销商档案。</p></article><article><header><h4>渠道订单</h4><span>实时规则校验</span></header><div class="line" v-for="x in data.orders" :key="x.id"><div><b>{{x.orderNo}}</b><small>{{x.productCode}} · {{x.regionCode}} · {{x.quantity}} 件</small></div><em>{{x.status}}</em></div><p v-if="!data.orders.length">暂无通过渠道门禁的订单。</p></article></section></template>
<style scoped>.head{background:#19344d;color:#fff;padding:27px 30px;border-radius:14px;display:flex;justify-content:space-between;align-items:end}.head small{color:#9dc1dc;letter-spacing:1.4px}.head h3{font-size:25px;margin:8px 0}.head p{color:#cbdce9;margin:0}.head button{background:#e6a74f;color:#172f46;border:0;border-radius:8px;padding:11px 17px;font-weight:700}.msg{padding:10px 14px;background:#eef5fa;border-left:3px solid #397aa7}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:#fff;border:1px solid #dce5ec;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#687988}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.line{display:flex;justify-content:space-between;align-items:center}.board header{padding-bottom:12px;border-bottom:1px solid #e9eef2}.board header button{border:0;background:transparent;color:#2674a8}.line{padding:14px 0;border-bottom:1px solid #edf1f4}.line small{display:block;color:#70808e;margin-top:4px}.line em{font-style:normal;font-size:12px;color:#236b9b}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
